 internal static Func<HyperVProfile,HyperVProbe> Availability=p=>{var probe=HyperVExecution.Probe(p with{DestinationCredentialTarget=null},false);return !probe.Available?probe:ServiceRunning("vmms")&&ServiceRunning("vmcompute")?probe:new(false,"Hyper-V VM services unavailable.");};
