 [System.Runtime.InteropServices.DllImport("advapi32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]private static extern IntPtr OpenSCManager(string? machine,string? database,uint access);
 [System.Runtime.InteropServices.DllImport("advapi32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]private static extern IntPtr OpenService(IntPtr manager,string name,uint access);
 [System.Runtime.InteropServices.DllImport("advapi32.dll")]private static extern bool QueryServiceStatus(IntPtr service,out ServiceStatus status);
 [System.Runtime.InteropServices.DllImport("advapi32.dll")]private static extern bool CloseServiceHandle(IntPtr handle);
